#!/bin/bash
# CIFAR-10, CNN 16-32-64 + GroupNorm, all 7 arms, forced onto CPU. Writes to
# benchmarks/outputs/cifar10/cnn_gn_cifar_cpu/.
#
# Hand-written, NOT generated by generate_jobs.py (which only knows the GPU protocol for the
# registered benchmarks/<model>/ folders). This is a one-off companion run to the existing
# cnn_gn_cifar_bn/ result (norm="bn", produced by a LOCAL --device cpu run), needed to isolate the
# GroupNorm-vs-BatchNorm variable cleanly:
#   - the original cnn_gn_cifar/ (norm="gn") run predates the --lr-schedule fix (no "lr_schedule"
#     key in its manifest.json at all) and shows the exact documented bug — adam/adamw's LR climbs
#     back up twice, since CosineAnnealingLR is periodic and they overshot the shared T_max under
#     the old "nominal" schedule (see benchmarks/common/schedules.py and CLAUDE.md's "Campaign-1
#     audit + the LR-schedule fix");
#   - it also ran on a GPU (device="auto" -> cuda) while cnn_gn_cifar_bn ran on CPU, a second
#     confound (fp32 reduction order differs, cf. fisher_ref/conventions.py's device-keyed
#     tolerance).
# This job fixes both at once: --lr-schedule budget (same protocol as the existing cnn_gn_cifar_bn
# run) and --device cpu (same device as that run), everything else identical to
# train_cnn_gn_cifar_all.sh. The only remaining variable between cnn_gn_cifar_cpu/ and
# cnn_gn_cifar_bn/ is --norm (gn vs bn), which is the point.
#
# Submit from the repository root:  sbatch benchmarks/slurm/cifar10/train_cnn_gn_cifar_cpu_all.sh

#SBATCH --account=def-msh-ab_cpu
#SBATCH --job-name=cnn_gn_cifar_cpu_all
#SBATCH --cpus-per-task=8
#SBATCH --mem=8G
#SBATCH --time=03:00:00
#SBATCH --output=benchmarks/slurm/logs/%x-%j.out

# --time: ESTIMATED, not measured on this cluster. Extrapolated from cnn_gn_cifar_bn's own local
# CPU run: sum of all 7 arms' total_s there is ~7194s (~2h00m) under the same WCT-budget protocol
# (diag runs the nominal 30 epochs unbudgeted, its measured time becomes every other arm's budget).
# 03:00:00 leaves ~1h of headroom for a slower cluster CPU node plus env setup, since this is the
# first time this model has run under --device cpu on this cluster.
# Dataset: cifar10, read from $DATA_ROOT (default $SLURM_SUBMIT_DIR/dataset).

set -euo pipefail
cd "$SLURM_SUBMIT_DIR"

module purge
module load StdEnv/2023 gcc/13.3 cuda/12.6 python/3.11.5

virtualenv --no-download "$SLURM_TMPDIR/env"
source "$SLURM_TMPDIR/env/bin/activate"
pip install --no-index --upgrade pip
pip install --no-index -r requirements-cluster.txt

export PYTHONPATH="$SLURM_SUBMIT_DIR/src:$SLURM_SUBMIT_DIR"
export OMP_NUM_THREADS="$SLURM_CPUS_PER_TASK"
DATA_ROOT="${DATA_ROOT:-$SLURM_SUBMIT_DIR/dataset}"

python -m benchmarks.cnn_gn_cifar.bench \
  --arms diag kfac ekfac tkfac tekfac adam adamw \
  --norm gn \
  --device cpu \
  --epochs 30 \
  --budget-mode wct \
  --reference-arm diag \
  --max-epoch-factor 3 \
  --lr-schedule budget \
  --num-workers 4 \
  --no-allow-download \
  --data-root "$DATA_ROOT" \
  --checkpoints 0,0.01,0.1,0.5,1 \
  --output-dir "$SLURM_SUBMIT_DIR/benchmarks/outputs/cifar10/cnn_gn_cifar_cpu"
